BEGIN; DO $$ BEGIN IF to_regprocedure('public.is_admin()') IS NULL OR to_regprocedure('public.admin_deactivate_customers_v1(uuid[])') IS NULL THEN RAISE EXCEPTION 'Thieu backend ngung Vendor ban truoc. Dung lai de kiem tra schema.'; END IF; IF to_regclass('public.customer_deactivation_audit') IS NULL THEN RAISE EXCEPTION 'Thieu bang audit ngung khach hang/Vendor.'; END IF; END $$; CREATE OR REPLACE FUNCTION public.admin_deactivate_customers_v1(p_customer_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_actor uuid:=auth.uid(); v_ids uuid[]; v_requested_count integer; v_locked_count integer; v_updated_count integer; v_now timestamptz:=now(); v_open_plan_count integer:=0; v_active_product_count integer:=0; v_active_child_count integer:=0; v_open_debt_count integer:=0; BEGIN IF v_actor IS NULL OR NOT public.is_admin() THEN RAISE EXCEPTION 'Chi Admin hoac Super Admin dang hoat dong moi duoc ngung khach hang/Vendor.' USING ERRCODE='42501'; END IF; SELECT array_agg(x.id ORDER BY x.id),count(*) INTO v_ids,v_requested_count FROM(SELECT DISTINCT u.id FROM unnest(COALESCE(p_customer_ids,ARRAY[]::uuid[])) AS u(id) WHERE u.id IS NOT NULL)x; IF COALESCE(v_requested_count,0)=0 THEN RAISE EXCEPTION 'Chua chon khach hang/Vendor can ngung.'; END IF; IF v_requested_count>100 THEN RAISE EXCEPTION 'Moi lan chi duoc ngung toi da 100 khach hang/Vendor.'; END IF; IF cardinality(p_customer_ids)<>v_requested_count THEN RAISE EXCEPTION 'Danh sach khach hang/Vendor co dong rong hoac bi trung. Khong dong nao thay doi.'; END IF; PERFORM c.id FROM public.customers c WHERE c.id=ANY(v_ids) ORDER BY c.id FOR UPDATE; GET DIAGNOSTICS v_locked_count=ROW_COUNT; IF v_locked_count<>v_requested_count THEN RAISE EXCEPTION 'Co khach hang/Vendor khong ton tai. Khong dong nao thay doi.'; END IF; IF EXISTS(SELECT 1 FROM public.customers c WHERE c.id=ANY(v_ids) AND (c.deleted_at IS NOT NULL OR c.is_active=false)) THEN RAISE EXCEPTION 'Co khach hang/Vendor da ngung truoc do. Khong dong nao thay doi.'; END IF; SELECT count(*) INTO v_active_child_count FROM public.customers c WHERE c.parent_customer_id=ANY(v_ids) AND c.deleted_at IS NULL AND c.is_active=true AND NOT(c.id=ANY(v_ids)); SELECT count(*) INTO v_active_product_count FROM public.products p WHERE p.customer_id=ANY(v_ids) AND p.deleted_at IS NULL AND COALESCE(p.is_active,true)=true; SELECT count(*) INTO v_open_plan_count FROM public.delivery_plans p WHERE (p.customer_id=ANY(v_ids) OR p.delivery_customer_id=ANY(v_ids)) AND p.deleted_at IS NULL AND GREATEST(COALESCE(p.planned_qty,0)+COALESCE(p.backlog_qty,0)-COALESCE(p.actual_qty,0),0)>0; IF to_regclass('public.accounting_debt_invoices') IS NOT NULL THEN EXECUTE 'SELECT count(*) FROM public.accounting_debt_invoices i WHERE i.customer_id=ANY($1) AND i.deleted_at IS NULL AND i.status=''open''' INTO v_open_debt_count USING v_ids; END IF; IF v_active_child_count>0 OR v_active_product_count>0 OR v_open_debt_count>0 THEN RAISE EXCEPTION 'Chua the ngung: con rang buoc dang mo (Vendor con: %, Ma hang: %, Cong no mo: %). Ke hoach dang giao khong bi xoa hay sua.',v_active_child_count,v_active_product_count,v_open_debt_count USING ERRCODE='23503'; END IF; INSERT INTO public.customer_deactivation_audit(customer_id,customer_code,customer_name,customer_kind,deactivated_by,deactivated_at) SELECT c.id,c.code,c.name,CASE WHEN c.parent_customer_id IS NULL THEN 'parent' ELSE 'vendor' END,v_actor,v_now FROM public.customers c WHERE c.id=ANY(v_ids) ORDER BY c.id; PERFORM set_config('app.customer_deactivation_v2','on',true); UPDATE public.customers SET is_active=false,deactivated_at=v_now,deactivated_by=v_actor WHERE id=ANY(v_ids) AND deleted_at IS NULL AND is_active=true; GET DIAGNOSTICS v_updated_count=ROW_COUNT; IF v_updated_count<>v_requested_count THEN RAISE EXCEPTION 'Khong ngung du so dong da chon. Toan bo thao tac duoc hoan tac.'; END IF; RETURN jsonb_build_object('success',true,'deactivated_count',v_updated_count,'open_plan_count',v_open_plan_count,'message',CASE WHEN v_open_plan_count>0 THEN format('Da ngung khach hang/Vendor. %s ke hoach dang giao duoc giu nguyen de tiep tuc xu ly.',v_open_plan_count) ELSE 'Da ngung khach hang/Vendor. Lich su van giu nguyen va con tra cuu duoc.' END); END $$; REVOKE ALL ON FUNCTION public.admin_deactivate_customers_v1(uuid[]) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_deactivate_customers_v1(uuid[]) TO authenticated; NOTIFY pgrst,'reload schema'; COMMIT;
